export interface AuthenticatedUser {
  userId: string;
  role: UserRole;
}

export function authenticateToken(
  authorizationHeader: string | undefined,
  jwtSecret: string,
): AuthenticatedUser {
  if (!authorizationHeader?.startsWith('Bearer ')) {
    throw new UnauthorizedError();
  }

  const token = authorizationHeader.slice('Bearer '.length).trim();
  if (!token) {
    throw new UnauthorizedError();
  }

  try {
    const payload = jwt.verify(token, jwtSecret);
    if (
      typeof payload === 'string' ||
      typeof payload.userId !== 'string' ||
      !Object.values(UserRole).includes(payload.role as UserRole)
    ) {
      throw new UnauthorizedError();
    }

    return { userId: payload.userId, role: payload.role as UserRole };
  } catch {
    throw new UnauthorizedError();
  }
}

export function requireAuth(jwtSecret: string): RequestHandler {
  return (req, _res, next) => {
    try {
      req.user = authenticateToken(req.get('authorization'), jwtSecret);
      next();
    } catch (error) {
      next(error);
    }
  };
}

export function requireRole(...roles: UserRole[]): RequestHandler {
  return (req, _res, next) => {
    if (!req.user) {
      return next(new UnauthorizedError());
    }

    if (!roles.includes(req.user.role)) {
      return next(new ForbiddenError());
    }

    next();
  };
}

export function cors(allowedOrigin: string): RequestHandler {
  return (req, res, next) => {
    res.header('Access-Control-Allow-Origin', allowedOrigin);
    res.header('Access-Control-Allow-Headers', 'Content-Type, Authorization');
    res.header('Access-Control-Allow-Methods', 'GET, POST, PUT, PATCH, DELETE, OPTIONS');

    if (req.method === 'OPTIONS') {
      res.sendStatus(204);
      return;
    }

    next();
  };
}

export const notFoundHandler: RequestHandler = (req, res) => {
  res.status(404).json({
    error: { message: `Route not found: ${req.method} ${req.originalUrl}` },
  });
};

export const errorHandler: ErrorRequestHandler = (err, _req, res, next) => {
  if (res.headersSent) {
    return next(err);
  }

  if (err instanceof ZodError) {
    return res.status(400).json({
      error: { message: 'Validation failed', details: err.flatten() },
    });
  }

  if (err instanceof AppError) {
    return res.status(err.statusCode).json({
      error: { message: err.message },
    });
  }

  console.error('Unhandled error:', err);
  return res.status(500).json({
    error: { message: 'Internal server error' },
  });
};

interface ValidationSchemas {
  body?: ZodType;
  params?: ZodType;
  query?: ZodType;
}

export const validate =
  (schemas: ValidationSchemas): RequestHandler =>
  (req, _res, next) => {
    try {
      if (schemas.body) {
        req.body = schemas.body.parse(req.body);
      }
      if (schemas.params) {
        req.params = schemas.params.parse(req.params) as typeof req.params;
      }
      if (schemas.query) {
        req.query = schemas.query.parse(req.query) as typeof req.query;
      }
      next();
    } catch (err) {
      next(err);
    }
  };

