export function createGoalsRouter(goalService: GoalService, requireAuth: RequestHandler): Router {
  const goalsRouter = Router();

  goalsRouter.use(requireAuth);

  goalsRouter.post(
    '/goals',
    requireRole(UserRole.SUPER_ADMIN, UserRole.TEAM_LEAD),
    validate({ body: createGoalSchema }),
    async (req, res, next) => {
      try {
        const goal = await goalService.createGoal(req.body, req.user!);
        res.status(201).json({ goal });
      } catch (error) {
        next(error);
      }
    },
  );

  goalsRouter.get(
    '/teams/:teamId/goals',
    validate({ params: teamIdSchema, query: goalFilterSchema }),
    async (req, res, next) => {
      try {
        const goals = await goalService.listTeamGoals(req.params.teamId, req.query, req.user!);
        res.status(200).json({ goals });
      } catch (error) {
        next(error);
      }
    },
  );

  goalsRouter.get('/goals/:id', validate({ params: goalIdSchema }), async (req, res, next) => {
    try {
      const goal = await goalService.getGoal(req.params.id, req.user!);
      res.status(200).json({ goal });
    } catch (error) {
      next(error);
    }
  });

  goalsRouter.patch(
    '/goals/:id',
    requireRole(UserRole.SUPER_ADMIN, UserRole.TEAM_LEAD),
    validate({ params: goalIdSchema, body: updateGoalSchema }),
    async (req, res, next) => {
      try {
        const goal = await goalService.updateGoal(req.params.id, req.body, req.user!);
        res.status(200).json({ goal });
      } catch (error) {
        next(error);
      }
    },
  );

  return goalsRouter;
}

export enum GoalStatus {
  PLANNED = 'PLANNED',
  ACTIVE = 'ACTIVE',
  COMPLETED = 'COMPLETED',
  CANCELLED = 'CANCELLED',
}

export enum GoalImportance {
  LOW = 'LOW',
  MEDIUM = 'MEDIUM',
  HIGH = 'HIGH',
}

@Entity({ name: 'goals' })
export class Goal {
  @PrimaryGeneratedColumn('uuid')
  id!: string;

  @Column({ name: 'team_id', type: 'uuid' })
  teamId!: string;

  @Column()
  title!: string;

  @Column({ type: 'text', default: '' })
  description!: string;

  @Column({ name: 'start_date', type: 'date' })
  startDate!: string;

  @Column({ type: 'date' })
  deadline!: string;

  @Column({
    type: 'enum',
    enum: GoalStatus,
    enumName: 'goal_status_enum',
    default: GoalStatus.PLANNED,
  })
  status!: GoalStatus;

  @Column({ type: 'enum', enum: GoalImportance, enumName: 'goal_importance_enum' })
  importance!: GoalImportance;

  @Column({ name: 'created_by_id', type: 'uuid' })
  createdById!: string;

  @CreateDateColumn({ name: 'created_at', type: 'timestamptz' })
  createdAt!: Date;

  @UpdateDateColumn({ name: 'updated_at', type: 'timestamptz' })
  updatedAt!: Date;
}

export interface CreateGoalRecord {
  teamId: string;
  title: string;
  description: string;
  startDate: string;
  deadline: string;
  status: GoalStatus;
  importance: GoalImportance;
  createdById: string;
}

export interface GoalFilter {
  status?: GoalStatus;
}

export interface GoalAccessFilter {
  teamId?: string;
}

export type UpdateGoalRecord = Partial<
  Pick<Goal, 'title' | 'description' | 'startDate' | 'deadline' | 'status' | 'importance'>
>;

export class GoalRepository extends BaseRepository<Goal> {
  constructor(dataSource: DataSource) {
    super(dataSource, Goal);
  }

  async create(goalRecord: CreateGoalRecord): Promise<Goal> {
    const goal = this.repo.create(goalRecord);
    return this.repo.save(goal);
  }

  findById(goalId: string, access: GoalAccessFilter = {}): Promise<Goal | null> {
    const query = this.repo.createQueryBuilder('goal').where('goal.id = :goalId', { goalId });

    if (access.teamId) {
      query.andWhere('goal.team_id = :accessTeamId', { accessTeamId: access.teamId });
    }

    return query.getOne();
  }

  findByTeam(teamId: string, filter: GoalFilter = {}): Promise<Goal[]> {
    const query = this.repo
      .createQueryBuilder('goal')
      .where('goal.team_id = :teamId', { teamId })
      .orderBy('goal.deadline', 'ASC')
      .addOrderBy('goal.title', 'ASC');

    if (filter.status) {
      query.andWhere('goal.status = :status', { status: filter.status });
    }

    return query.getMany();
  }

  async update(goalId: string, changes: UpdateGoalRecord): Promise<Goal> {
    await this.repo.update(goalId, changes);
    return this.repo.findOneByOrFail({ id: goalId });
  }
}

