export interface CreateGoalDto {
  teamId: string;
  title: string;
  description?: string;
  startDate: string;
  deadline: string;
  importance: GoalImportance;
}

export type UpdateGoalDto = Partial<
  Pick<CreateGoalDto, 'title' | 'description' | 'startDate' | 'deadline' | 'importance'> & {
    status: GoalStatus;
  }
>;

export interface GoalProjection {
  id: string;
  teamId: string;
  title: string;
  description: string;
  startDate: string;
  deadline: string;
  status: GoalStatus;
  importance: GoalImportance;
  createdById: string;
  progress: number;
  noTasksYet: boolean;
  taskStatusBreakdown: GoalTaskStatusBreakdown;
  createdAt: Date;
  updatedAt: Date;
}

export interface GoalTaskStatusBreakdown {
  total: number;
  todo: number;
  inProgress: number;
  blocked: number;
  done: number;
}

export interface GoalProgress {
  progress: number;
  noTasksYet: boolean;
  taskStatusBreakdown: GoalTaskStatusBreakdown;
}

export class GoalService {
  constructor(
    private readonly goalRepository: GoalRepository,
    private readonly taskRepository: TaskRepository,
    private readonly scopeService: ScopeService,
  ) {}

  async createGoal(dto: CreateGoalDto, caller: AuthenticatedUser): Promise<GoalProjection> {
    await this.assertCanManageTeam(caller, dto.teamId);
    this.assertValidDates(dto.startDate, dto.deadline);

    const goal = await this.goalRepository.create({
      teamId: dto.teamId,
      title: dto.title,
      description: dto.description ?? '',
      startDate: dto.startDate,
      deadline: dto.deadline,
      status: GoalStatus.PLANNED,
      importance: dto.importance,
      createdById: caller.userId,
    });

    return this.toProjection(goal, this.emptyProgress());
  }

  async listTeamGoals(
    teamId: string,
    filter: GoalFilter,
    caller: AuthenticatedUser,
  ): Promise<GoalProjection[]> {
    await this.assertCanViewTeam(caller, teamId);
    const goals = await this.goalRepository.findByTeam(teamId, filter);
    const countsByGoal = await this.taskRepository.countByGoalIdsAndStatus(
      goals.map((goal) => goal.id),
    );
    return goals.map((goal) =>
      this.toProjection(goal, this.progressFromCounts(countsByGoal.get(goal.id)!)),
    );
  }

  async getGoal(goalId: string, caller: AuthenticatedUser): Promise<GoalProjection> {
    const existingGoal = await this.goalRepository.findById(goalId);
    if (!existingGoal) {
      throw new NotFoundError('Goal not found');
    }

    await this.assertCanViewTeam(caller, existingGoal.teamId);
    const scopedGoal = await this.goalRepository.findById(goalId, { teamId: existingGoal.teamId });
    if (!scopedGoal) {
      throw new ForbiddenError('You do not have access to this goal');
    }

    return this.toProjection(scopedGoal, await this.calculateProgress(goalId));
  }

  async updateGoal(
    goalId: string,
    dto: UpdateGoalDto,
    caller: AuthenticatedUser,
  ): Promise<GoalProjection> {
    const existingGoal = await this.goalRepository.findById(goalId);
    if (!existingGoal) {
      throw new NotFoundError('Goal not found');
    }

    await this.assertCanManageTeam(caller, existingGoal.teamId);
    const scopedGoal = await this.goalRepository.findById(goalId, { teamId: existingGoal.teamId });
    if (!scopedGoal) {
      throw new ForbiddenError('You do not have access to this goal');
    }

    this.assertValidDates(
      dto.startDate ?? scopedGoal.startDate,
      dto.deadline ?? scopedGoal.deadline,
    );
    const updatedGoal = await this.goalRepository.update(goalId, dto as UpdateGoalRecord);
    return this.toProjection(updatedGoal, await this.calculateProgress(goalId));
  }

  async calculateProgress(goalId: string): Promise<GoalProgress> {
    const counts = await this.taskRepository.countByGoalAndStatus(goalId);
    return this.progressFromCounts(counts);
  }

  private async assertCanManageTeam(caller: AuthenticatedUser, teamId: string): Promise<void> {
    if (caller.role === UserRole.SUPER_ADMIN) return;
    if (caller.role !== UserRole.TEAM_LEAD) {
      throw new ForbiddenError('Employees cannot manage goals');
    }
    await this.scopeService.assertTeamLeadOf(caller.userId, teamId);
  }

  private async assertCanViewTeam(caller: AuthenticatedUser, teamId: string): Promise<void> {
    if (caller.role === UserRole.SUPER_ADMIN) return;
    if (caller.role === UserRole.TEAM_LEAD) {
      await this.scopeService.assertTeamLeadOf(caller.userId, teamId);
      return;
    }
    await this.scopeService.assertMemberOf(caller.userId, teamId);
  }

  private assertValidDates(startDate: string, deadline: string): void {
    if (deadline <= startDate) {
      throw new ValidationError('Deadline must fall after the start date');
    }
  }

  private emptyProgress(): GoalProgress {
    return this.progressFromCounts({
      [TaskStatus.TODO]: 0,
      [TaskStatus.IN_PROGRESS]: 0,
      [TaskStatus.BLOCKED]: 0,
      [TaskStatus.DONE]: 0,
    });
  }

  private progressFromCounts(counts: TaskStatusCounts): GoalProgress {
    const total =
      counts[TaskStatus.TODO] +
      counts[TaskStatus.IN_PROGRESS] +
      counts[TaskStatus.BLOCKED] +
      counts[TaskStatus.DONE];

    return {
      progress: total === 0 ? 0 : (counts[TaskStatus.DONE] / total) * 100,
      noTasksYet: total === 0,
      taskStatusBreakdown: {
        total,
        todo: counts[TaskStatus.TODO],
        inProgress: counts[TaskStatus.IN_PROGRESS],
        blocked: counts[TaskStatus.BLOCKED],
        done: counts[TaskStatus.DONE],
      },
    };
  }

  private toProjection(goal: Goal, progress: GoalProgress): GoalProjection {
    return {
      id: goal.id,
      teamId: goal.teamId,
      title: goal.title,
      description: goal.description,
      startDate: goal.startDate,
      deadline: goal.deadline,
      status: goal.status,
      importance: goal.importance,
      createdById: goal.createdById,
      ...progress,
      createdAt: goal.createdAt,
      updatedAt: goal.updatedAt,
    };
  }
}

constructor(
    private readonly goalRepository: GoalRepository,
    private readonly taskRepository: TaskRepository,
    private readonly scopeService: ScopeService,
  ) {}

async createGoal(dto: CreateGoalDto, caller: AuthenticatedUser): Promise<GoalProjection> {
    await this.assertCanManageTeam(caller, dto.teamId);
    this.assertValidDates(dto.startDate, dto.deadline);

    const goal = await this.goalRepository.create({
      teamId: dto.teamId,
      title: dto.title,
      description: dto.description ?? '',
      startDate: dto.startDate,
      deadline: dto.deadline,
      status: GoalStatus.PLANNED,
      importance: dto.importance,
      createdById: caller.userId,
    });

    return this.toProjection(goal, this.emptyProgress());
  }

async listTeamGoals(
    teamId: string,
    filter: GoalFilter,
    caller: AuthenticatedUser,
  ): Promise<GoalProjection[]> {
    await this.assertCanViewTeam(caller, teamId);
    const goals = await this.goalRepository.findByTeam(teamId, filter);
    const countsByGoal = await this.taskRepository.countByGoalIdsAndStatus(
      goals.map((goal) => goal.id),
    );
    return goals.map((goal) =>
      this.toProjection(goal, this.progressFromCounts(countsByGoal.get(goal.id)!)),
    );
  }

async getGoal(goalId: string, caller: AuthenticatedUser): Promise<GoalProjection> {
    const existingGoal = await this.goalRepository.findById(goalId);
    if (!existingGoal) {
      throw new NotFoundError('Goal not found');
    }

    await this.assertCanViewTeam(caller, existingGoal.teamId);
    const scopedGoal = await this.goalRepository.findById(goalId, { teamId: existingGoal.teamId });
    if (!scopedGoal) {
      throw new ForbiddenError('You do not have access to this goal');
    }

    return this.toProjection(scopedGoal, await this.calculateProgress(goalId));
  }

async updateGoal(
    goalId: string,
    dto: UpdateGoalDto,
    caller: AuthenticatedUser,
  ): Promise<GoalProjection> {
    const existingGoal = await this.goalRepository.findById(goalId);
    if (!existingGoal) {
      throw new NotFoundError('Goal not found');
    }

    await this.assertCanManageTeam(caller, existingGoal.teamId);
    const scopedGoal = await this.goalRepository.findById(goalId, { teamId: existingGoal.teamId });
    if (!scopedGoal) {
      throw new ForbiddenError('You do not have access to this goal');
    }

    this.assertValidDates(
      dto.startDate ?? scopedGoal.startDate,
      dto.deadline ?? scopedGoal.deadline,
    );
    const updatedGoal = await this.goalRepository.update(goalId, dto as UpdateGoalRecord);
    return this.toProjection(updatedGoal, await this.calculateProgress(goalId));
  }

async calculateProgress(goalId: string): Promise<GoalProgress> {
    const counts = await this.taskRepository.countByGoalAndStatus(goalId);
    return this.progressFromCounts(counts);
  }

private async assertCanManageTeam(caller: AuthenticatedUser, teamId: string): Promise<void> {
    if (caller.role === UserRole.SUPER_ADMIN) return;
    if (caller.role !== UserRole.TEAM_LEAD) {
      throw new ForbiddenError('Employees cannot manage goals');
    }
    await this.scopeService.assertTeamLeadOf(caller.userId, teamId);
  }

private async assertCanViewTeam(caller: AuthenticatedUser, teamId: string): Promise<void> {
    if (caller.role === UserRole.SUPER_ADMIN) return;
    if (caller.role === UserRole.TEAM_LEAD) {
      await this.scopeService.assertTeamLeadOf(caller.userId, teamId);
      return;
    }
    await this.scopeService.assertMemberOf(caller.userId, teamId);
  }

private assertValidDates(startDate: string, deadline: string): void {
    if (deadline <= startDate) {
      throw new ValidationError('Deadline must fall after the start date');
    }
  }

private emptyProgress(): GoalProgress {
    return this.progressFromCounts({
      [TaskStatus.TODO]: 0,
      [TaskStatus.IN_PROGRESS]: 0,
      [TaskStatus.BLOCKED]: 0,
      [TaskStatus.DONE]: 0,
    });
  }

private progressFromCounts(counts: TaskStatusCounts): GoalProgress {
    const total =
      counts[TaskStatus.TODO] +
      counts[TaskStatus.IN_PROGRESS] +
      counts[TaskStatus.BLOCKED] +
      counts[TaskStatus.DONE];

    return {
      progress: total === 0 ? 0 : (counts[TaskStatus.DONE] / total) * 100,
      noTasksYet: total === 0,
      taskStatusBreakdown: {
        total,
        todo: counts[TaskStatus.TODO],
        inProgress: counts[TaskStatus.IN_PROGRESS],
        blocked: counts[TaskStatus.BLOCKED],
        done: counts[TaskStatus.DONE],
      },
    };
  }

private toProjection(goal: Goal, progress: GoalProgress): GoalProjection {
    return {
      id: goal.id,
      teamId: goal.teamId,
      title: goal.title,
      description: goal.description,
      startDate: goal.startDate,
      deadline: goal.deadline,
      status: goal.status,
      importance: goal.importance,
      createdById: goal.createdById,
      ...progress,
      createdAt: goal.createdAt,
      updatedAt: goal.updatedAt,
    };
  }

export function createTasksRouter(taskService: TaskService, requireAuth: RequestHandler): Router {
  const tasksRouter = Router();

  tasksRouter.use(requireAuth);

  tasksRouter.post(
    '/goals/:goalId/tasks',
    requireRole(UserRole.SUPER_ADMIN, UserRole.TEAM_LEAD),
    validate({ params: goalIdSchema, body: createTaskSchema }),
    async (req, res, next) => {
      try {
        const task = await taskService.createTask(req.params.goalId, req.body, req.user!);
        res.status(201).json({ task });
      } catch (error) {
        next(error);
      }
    },
  );

  tasksRouter.get(
    '/goals/:goalId/tasks',
    validate({ params: goalIdSchema }),
    async (req, res, next) => {
      try {
        const tasks = await taskService.listGoalTasks(req.params.goalId, req.user!);
        res.status(200).json({ tasks });
      } catch (error) {
        next(error);
      }
    },
  );

  tasksRouter.get(
    '/tasks/mine',
    validate({ query: myTaskFilterSchema }),
    async (req, res, next) => {
      try {
        const tasks = await taskService.getMyTasks(
          req.user!.userId,
          req.query as MyTaskFilter,
        );
        res.status(200).json({ tasks });
      } catch (error) {
        next(error);
      }
    },
  );

  tasksRouter.get(
    '/tasks/:id/effort',
    requireRole(UserRole.SUPER_ADMIN, UserRole.TEAM_LEAD),
    validate({ params: taskIdSchema }),
    async (req, res, next) => {
      try {
        const effort = await taskService.getTaskEffort(req.params.id, req.user!);
        res.status(200).json({ effort });
      } catch (error) {
        next(error);
      }
    },
  );

  tasksRouter.get('/tasks/:id', validate({ params: taskIdSchema }), async (req, res, next) => {
    try {
      const task = await taskService.getTask(req.params.id, req.user!);
      res.status(200).json({ task });
    } catch (error) {
      next(error);
    }
  });

  tasksRouter.patch(
    '/tasks/:id',
    requireRole(UserRole.SUPER_ADMIN, UserRole.TEAM_LEAD),
    validate({ params: taskIdSchema, body: updateTaskSchema }),
    async (req, res, next) => {
      try {
        const task = await taskService.updateTask(req.params.id, req.body, req.user!);
        res.status(200).json({ task });
      } catch (error) {
        next(error);
      }
    },
  );

  tasksRouter.patch(
    '/tasks/:id/status',
    validate({ params: taskIdSchema, body: updateTaskStatusSchema }),
    async (req, res, next) => {
      try {
        const task = await taskService.updateStatus(req.params.id, req.body.status, req.user!);
        res.status(200).json({ task });
      } catch (error) {
        next(error);
      }
    },
  );

  tasksRouter.put(
    '/tasks/:id/assignee',
    requireRole(UserRole.TEAM_LEAD),
    validate({ params: taskIdSchema, body: assignTaskSchema }),
    async (req, res, next) => {
      try {
        const task = await taskService.assignTask(
          req.params.id,
          req.body.assigneeId,
          req.user!,
        );
        res.status(200).json({ task });
      } catch (error) {
        next(error);
      }
    },
  );

  return tasksRouter;
}

export enum TaskStatus {
