}

export function TeamMemberAssignmentForm({
  teamId,
  refreshVersion,
  onMemberAdded,
}: TeamMemberAssignmentFormProps) {
  const [employees, setEmployees] = useState<UnassignedEmployee[]>([]);
  const [selectedUserId, setSelectedUserId] = useState('');
  const [isLoading, setIsLoading] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState('');
  const [successMessage, setSuccessMessage] = useState('');

  useEffect(() => {
    let requestWasCancelled = false;

    setIsLoading(true);
    setError('');
    apiRequest<UsersResponse>('/users?role=EMPLOYEE&unassigned=true')
      .then((response) => {
        if (requestWasCancelled) return;
        setEmployees(response.users);
        setSelectedUserId((currentUserId) => {
          const currentUserIsAvailable = response.users.some(
            (employee) => employee.id === currentUserId,
          );
          return currentUserIsAvailable ? currentUserId : (response.users[0]?.id ?? '');
        });
      })
      .catch((requestError) => {
        if (!requestWasCancelled) {
          setError(
            requestError instanceof Error
              ? requestError.message
              : 'Unable to load unassigned employees',
          );
        }
      })
      .finally(() => {
        if (!requestWasCancelled) setIsLoading(false);
      });

    return () => {
      requestWasCancelled = true;
    };
  }, [refreshVersion, teamId]);

  async function handleSubmit(event: FormEvent<HTMLFormElement>): Promise<void> {
    event.preventDefault();
    setError('');
    setSuccessMessage('');
    setIsSubmitting(true);

    try {
      const response = await apiRequest<TeamMemberResponse>(`/teams/${teamId}/members`, {
        method: 'POST',
        body: JSON.stringify({ userId: selectedUserId }),
      });
      setEmployees((currentEmployees) =>
        currentEmployees.filter((employee) => employee.id !== selectedUserId),
      );
      setSelectedUserId('');
      setSuccessMessage(`${response.member.name} was added to the team.`);
      onMemberAdded();
    } catch (requestError) {
      setError(requestError instanceof Error ? requestError.message : 'Unable to add the employee');
    } finally {
      setIsSubmitting(false);
    }
  }

  return (
    <section className="panel" aria-labelledby="add-member-title">
      <div className="panel-heading">
        <p className="eyebrow">Membership</p>
        <h2 id="add-member-title">Add employee</h2>
        <p>Choose an employee who is not currently assigned to a team.</p>
      </div>

      {isLoading ? (
        <p className="list-message">Loading unassigned employees…</p>
      ) : (
        <form className="member-management-form" onSubmit={handleSubmit}>
          <label htmlFor="employee-to-add">Employee</label>
          <select
            id="employee-to-add"
            value={selectedUserId}
            onChange={(event) => setSelectedUserId(event.target.value)}
            disabled={employees.length === 0 || isSubmitting}
          >
            {employees.length === 0 ? (
              <option value="">No unassigned employees</option>
            ) : (
              employees.map((employee) => (
                <option key={employee.id} value={employee.id}>
                  {employee.name} — {employee.email}
                </option>
              ))
            )}
          </select>

          {error && (
            <p className="form-error" role="alert">
              {error}
            </p>
          )}
          {successMessage && (
            <p className="form-success" role="status">
              {successMessage}
            </p>
          )}

          <button
            className="submit-button"
            type="submit"
            disabled={!selectedUserId || isSubmitting}
          >
            {isSubmitting ? 'Adding employee…' : 'Add to team'}
          </button>
        </form>
      )}
    </section>
  );
}

interface TeamTimesheetTableProps {
  entries: TeamTimesheetEntry[];
}

interface MemberEntries {
  employee: TeamTimesheetEntry['employee'];
  entries: TeamTimesheetEntry[];
}

function groupEntriesByMember(entries: TeamTimesheetEntry[]): MemberEntries[] {
  const groups = new Map<string, MemberEntries>();

  for (const entry of entries) {
    const existingGroup = groups.get(entry.employee.id);
    if (existingGroup) {
      existingGroup.entries.push(entry);
    } else {
      groups.set(entry.employee.id, {
        employee: entry.employee,
        entries: [entry],
      });
    }
  }

  return [...groups.values()];
}

export function TeamTimesheetTable({ entries }: TeamTimesheetTableProps) {
  const memberGroups = groupEntriesByMember(entries);

  if (memberGroups.length === 0) {
    return <p className="empty-state">No time was recorded in this date range.</p>;
  }

  return (
    <div className="team-timesheet-groups">
      {memberGroups.map((group) => {
        const totalHours = group.entries.reduce((total, entry) => total + entry.hoursSpent, 0);

        return (
          <section className="team-timesheet-member" key={group.employee.id}>
            <div className="team-timesheet-member-heading">
              <h3>{group.employee.name}</h3>
              <span>{totalHours.toLocaleString()} hours</span>
            </div>
            <div className="table-wrapper">
              <table className="team-timesheets-table">
                <thead>
                  <tr>
                    <th scope="col">Work date</th>
                    <th scope="col">Task</th>
                    <th scope="col">Goal</th>
                    <th scope="col">Hours</th>
                    <th scope="col">Work note</th>
                  </tr>
                </thead>
                <tbody>
                  {group.entries.map((entry) => (
                    <tr key={entry.id}>
                      <td>{entry.workDate}</td>
                      <td>
                        <Link className="task-link" to={`/tasks/${entry.task.id}`}>
                          {entry.task.title}
                        </Link>
                      </td>
                      <td>{entry.goal.title}</td>
                      <td>{entry.hoursSpent}</td>
                      <td>{entry.workNote || 'No work note'}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </section>
        );
      })}
    </div>
  );
}

