                                  to={`/goals/${goal.id}`}
                                >
                                  {goal.title}
                                </Link>
                              </td>
                              <td>
                                <span>{goal.deadline}</span>
                                <small
                                  className={
                                    deadlineDisplay.overdue
                                      ? "goal-deadline-text overdue"
                                      : "goal-deadline-text"
                                  }
                                >
                                  {deadlineDisplay.text}
                                </small>
                              </td>
                              <td>
                                <GoalStatusBadge
                                  status={goal.status}
                                  deadline={goal.deadline}
                                />
                              </td>
                              <td className="goal-progress-cell">
                                <GoalProgress
                                  progress={goal.progress}
                                  noTasksYet={goal.noTasksYet}
                                  breakdown={goal.taskStatusBreakdown}
                                  compact
                                />
                              </td>
                            </tr>
                          );
                        })}
                      </tbody>
                    </table>
                  </div>
                )}
              </section>
            </div>
          </>
        )}
      </main>
    </div>
  );
}

export function TeamTimesheetsPage() {
  const { id } = useParams();
  const [team, setTeam] = useState<TeamDetails | null>(null);
  const [timesheets, setTimesheets] = useState<TeamTimesheetsResponse | null>(null);
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const [isLoading, setIsLoading] = useState(true);
  const [isFiltering, setIsFiltering] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    let requestWasCancelled = false;

    async function loadInitialTimesheets(): Promise<void> {
      setIsLoading(true);
      setError('');

      try {
        const [teamResponse, timesheetResponse] = await Promise.all([
          apiRequest<TeamDetailsResponse>(`/teams/${id}`),
          apiRequest<TeamTimesheetsResponse>(`/teams/${id}/timesheets`),
        ]);

        if (!requestWasCancelled) {
          setTeam(teamResponse.team);
          setTimesheets(timesheetResponse);
          setFrom(timesheetResponse.range.from);
          setTo(timesheetResponse.range.to);
        }
      } catch (requestError) {
        if (!requestWasCancelled) {
          setError(
            requestError instanceof Error
              ? requestError.message
              : 'Unable to load team timesheets',
          );
        }
      } finally {
        if (!requestWasCancelled) setIsLoading(false);
      }
    }

    void loadInitialTimesheets();

    return () => {
      requestWasCancelled = true;
    };
  }, [id]);

  async function filterTimesheets(event: FormEvent<HTMLFormElement>): Promise<void> {
    event.preventDefault();
    setIsFiltering(true);
    setError('');

    try {
      const response = await apiRequest<TeamTimesheetsResponse>(
        `/teams/${id}/timesheets?from=${from}&to=${to}`,
      );
      setTimesheets(response);
    } catch (requestError) {
      setError(
        requestError instanceof Error
          ? requestError.message
          : 'Unable to filter team timesheets',
      );
    } finally {
      setIsFiltering(false);
    }
  }

  return (
    <div className="app-shell">
      <Navigation />
      <main className="team-timesheets-page">
        <Link className="back-link" to={`/teams/${id}`}>
          ← Back to team
        </Link>

        {isLoading && <p className="list-message">Loading team timesheets…</p>}
        {error && (
          <p className="form-error" role="alert">
            {error}
          </p>
        )}

        {!isLoading && team && timesheets && (
          <>
            <header className="page-heading team-timesheets-heading">
              <div>
                <p className="eyebrow">Team timesheets</p>
                <h1>{team.name}</h1>
                <p>Review time recorded by each team member.</p>
              </div>
            </header>

            <section className="panel team-timesheets-panel" aria-labelledby="entries-title">
              <div className="team-timesheet-toolbar">
                <div>
                  <p className="eyebrow">Recorded time</p>
                  <h2 id="entries-title">Entries by member</h2>
                </div>
                <form className="team-timesheet-filter" onSubmit={filterTimesheets}>
                  <label>
                    From
                    <input
                      type="date"
                      value={from}
                      required
                      onChange={(event) => setFrom(event.target.value)}
                    />
                  </label>
                  <label>
                    To
                    <input
                      type="date"
                      value={to}
                      required
                      onChange={(event) => setTo(event.target.value)}
                    />
                  </label>
                  <button className="submit-button" type="submit" disabled={isFiltering}>
                    {isFiltering ? 'Filtering…' : 'Apply filter'}
                  </button>
                </form>
              </div>

              {isFiltering ? (
                <p className="list-message">Filtering entries…</p>
              ) : (
                <TeamTimesheetTable entries={timesheets.entries} />
              )}
            </section>
          </>
        )}
      </main>
    </div>
  );
}

export function TeamsPage() {
  const { user } = useAuth();
  const [teams, setTeams] = useState<Team[]>([]);
  const [refreshVersion, setRefreshVersion] = useState(0);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    let requestWasCancelled = false;

    setIsLoading(true);
    setError('');
    apiRequest<TeamsResponse>('/teams')
      .then((response) => {
        if (!requestWasCancelled) setTeams(response.teams);
      })
      .catch((requestError) => {
        if (!requestWasCancelled) {
          setError(
            requestError instanceof Error
              ? requestError.message
              : 'Unable to load teams',
          );
        }
      })
      .finally(() => {
        if (!requestWasCancelled) setIsLoading(false);
      });

    return () => {
      requestWasCancelled = true;
    };
  }, [refreshVersion]);

  const isSuperAdmin = user?.role === 'SUPER_ADMIN';
  const emptyMessage = isSuperAdmin
    ? 'No teams have been created yet.'
    : 'You are not currently assigned as a team lead.';

  return (
    <div className="app-shell">
      <Navigation />
      <main className="teams-page">
        <header className="page-heading">
          <div>
            <p className="eyebrow">Company structure</p>
            <h1>{isSuperAdmin ? 'Teams' : 'My team'}</h1>
            <p>View team capacity, leadership, and membership.</p>
          </div>
        </header>

        <div className={isSuperAdmin ? 'teams-layout' : undefined}>
          {isSuperAdmin && (
            <TeamCreationForm
              onCreated={() => setRefreshVersion((version) => version + 1)}
            />
          )}

          <section
            className="panel teams-list-panel"
            aria-labelledby="teams-list-title"
          >
            <div className="list-heading">
              <div>
                <p className="eyebrow">Directory</p>
                <h2 id="teams-list-title">Team list</h2>
              </div>
            </div>

            {isLoading && <p className="list-message">Loading teams…</p>}
            {error && (
              <p className="form-error" role="alert">
                {error}
              </p>
            )}
            {!isLoading && !error && teams.length === 0 && (
              <p className="list-message">{emptyMessage}</p>
            )}
            {!isLoading && !error && teams.length > 0 && (
              <div className="table-wrapper">
                <table className="teams-table">
                  <thead>
                    <tr>
                      <th scope="col">Team</th>
                      <th scope="col">Description</th>
                      <th scope="col">Weekly capacity</th>
                      <th scope="col">Lead</th>
                    </tr>
                  </thead>
                  <tbody>
                    {teams.map((team) => (
                      <tr key={team.id}>
                        <td>
                          <Link className="team-link" to={`/teams/${team.id}`}>
                            {team.name}
                          </Link>
                        </td>
                        <td>{team.description || 'No description'}</td>
                        <td>{team.weeklyCapacityHours} hours</td>
                        <td>{team.leadId ? 'Assigned' : 'Not assigned'}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </section>
        </div>
      </main>
    </div>
  );
}

